import subprocess, time, calendar
def epoch(y,mo,d,h,mi,s): return calendar.timegm((y,mo,d,h,mi,s,0,0,0))
def get_grid(sess="px"):
    out=subprocess.run(["tmux","capture-pane","-t",sess,"-p","-e"],capture_output=True,text=True).stdout
    rows=[]
    width=0
    for line in out.split("\n"):
        chars=[]; cols=[]; bg=None; fg=None; bold=False; i=0; 
        while i<len(line):
            if line[i]=='\x1b' and i+1<len(line) and line[i+1]=='[':
                j=line.find('m',i); code=line[i+2:j] if j!=-1 else ""
                if j==-1: break
                for p in code.split(';'):
                    try: n=int(p) if p else 0
                    except: n=0
                    if 40<=n<=49: bg=n
                    elif 30<=n<=39: fg=n
                    elif 100<=n<=107: bg=n
                    elif 90<=n<=97: fg=n
                    elif n==1: bold=True
                    elif n==0: bg=fg=None; bold=False
                i=j+1; continue
            chars.append(line[i]); cols.append((bg,fg,bold)); i+=1
        w=len(chars)
        grid=''.join('#' if (bg is not None and bg!=49) else (ch if ch!=' ' else '.') for ch,(bg,fg,b) in zip(chars,cols))
        rows.append((grid,''.join(chars),cols))
    return rows
def show(rows, label=""):
    print(f"--- {label}")
    for idx,(g,t,c) in enumerate(rows):
        s=g.rstrip('.')
        if s or t.strip():
            print(f"{idx:2}: {s}")
    texts=[(i,t.strip()) for i,(g,t,c) in enumerate(rows) if t.strip()]
    if texts: print(" texts:",texts)
    uniq=set()
    for g,t,c in rows:
        for col in c: uniq.add(col)
    print(" colors:",sorted(uniq,key=str))
def start(args="", e=None, w=80,h=24, sess="px", exe="/workspace/executable", extra="TZ=UTC0", wait=0.7):
    subprocess.run(["tmux","kill-session","-t",sess],capture_output=True)
    env=""
    if e is not None: env+=f'FAKE_EPOCH={e} LD_PRELOAD=/tmp/probe/fakelib.so '
    env+=extra+" "
    cmd=f'{env} TERM=xterm-256color {exe} {args}'
    subprocess.run(["tmux","new-session","-d","-s",sess,"-x",str(w),"-y",str(h),cmd],check=False)
    time.sleep(wait)
    alive=subprocess.run(["tmux","has-session","-t",sess],capture_output=True).returncode==0
    return alive
def kill(sess="px"):
    subprocess.run(["tmux","kill-session","-t",sess],capture_output=True); time.sleep(0.1)
def keys(*ks, sess="px", delay=0.35):
    for k in ks:
        if isinstance(k,(list,tuple)): subprocess.run(["tmux","send-keys","-t",sess]+list(k))
        else: subprocess.run(["tmux","send-keys","-t",sess,k])
        time.sleep(delay)
def alive(sess="px"):
    return subprocess.run(["tmux","has-session","-t",sess],capture_output=True).returncode==0
