        int cy = (maxy - ttyclock.h) / 2 - 1;
        if (cx >= 0) ttyclock.x = cx;
        if (cy >= 0) ttyclock.y = cy;
    } else {
        int xmax = maxx - ttyclock.w;
        int ymax = maxy - 9;
        if (xmax >= 0 && ttyclock.x > xmax) ttyclock.x = xmax;
        if (ymax >= 0 && ttyclock.y > ymax) ttyclock.y = ymax;
    }

