    int dlen = (int)strlen(ttyclock.datestr);
    ttyclock.date_w = 0;
    if (show_date) {
        int len_str = dlen < ttyclock.w ? dlen : ttyclock.w;
        ttyclock.date_w = len_str + 2;
    }

