        int so1 = ttyclock.option.center
            ? (ttyclock.date_w > 10 ? ttyclock.date_w + 2 : 12)
            : (ttyclock.w - dlen) / 2 + 1;
        int so2 = ttyclock.w - ttyclock.date_w +
                  ((ttyclock.date_w - dlen) / 2);
        ttyclock.date_x = ttyclock.x + (so1 > so2 ? so2 : so1) - 1;
        ttyclock.date_y = ttyclock.option.center
            ? (maxy - ttyclock.h) / 2 + 6 : ttyclock.y + ttyclock.h - 1;
        ttyclock.datewin = newwin(3, ttyclock.date_w,
