#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <strings.h>
#include <unistd.h>
#include <getopt.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <sys/stat.h>
#include <ncurses.h>
#include "ttyclock.h"

static const char usage_str[] =
"usage : tty-clock [-iuvsScbtrahDBxn] [-C [0-7]] [-f format] [-d delay] [-a nsdelay] [-T tty] \n"
"    -s            Show seconds                                   \n"
"    -S            Screensaver mode                               \n"
"    -x            Show box                                       \n"
"    -c            Set the clock at the center of the terminal    \n"
"    -C [0-7]      Set the clock color                            \n"
"    -b            Use bold colors                                \n"
"    -t            Set the hour in 12h format                     \n"
"    -u            Use UTC time                                   \n"
"    -T tty        Display the clock on the specified terminal    \n"
"    -r            Do rebound the clock                           \n"
"    -f format     Set the date format                            \n"
"    -n            Don't quit on keypress                         \n"
"    -v            Show tty-clock version                         \n"
"    -i            Show some info about tty-clock                 \n"
"    -h            Show this page                                 \n"
"    -D            Hide date                                      \n"
"    -B            Enable blinking colon                          \n"
"    -d delay      Set the delay between two redraws of the clock. Default 1s. \n"
"    -a nsdelay    Additional delay between two redraws in nanoseconds. Default 0ns.\n";

static void usage(void) {
    printf("%s", usage_str);
    exit(0);
}

static void sig_handler(int sig) {
    (void)sig;
    sigflag = 1;
}

/* Direction of rebound travel. */
static int xdir = 1;
static int ydir = 1;

/* A key picked up by the screensaver probe but not yet acted on. */
static int pending = ERR;
/* A key already acted on while the screensaver still has to notice it. */
static int ss_pending = ERR;
/* Set when a handled key changed the window layout. */
static int layout_dirty = 0;

static int input_fd(void) {
    /* The stream the clock screen reads keys from.
     * When -T was used, try to recover the descriptor from the tty
     * name; input will be opened once and cached. */
    static int fd = -2;
    if (fd == -2) {
        if (ttyclock.option.tty) {
            FILE *probe = fopen(ttyclock.option.tty, "r+");
            fd = probe ? fileno(probe) : STDIN_FILENO;
            /* Note: this descriptor is NOT used for curses input
             * (the SCREEN has its own); it is only polled to decide
             * when to sleep, and polling it must not consume input. */
        } else {
            fd = STDIN_FILENO;
        }
        /* In -T mode the reference behaviour sleeps with nanosleep
         * and never wakes early on the remote tty either, which the
         * wait routine reproduces without needing this descriptor.
         * Keep it for the local case only. */
        if (ttyclock.option.tty) fd = -1;
    }
    return fd;
}

/*
 * Sleep for the configured delay, waking early when a key becomes
 * readable on the local input.  Returns 1 if input is ready.
 *
 * In screensaver mode (and always when showing on a remote tty)
 * the sleep is never shortened: keys are only discovered at the
 * end of the delay.  A zero total delay is still a nanosleep.
 */
static int wait_delay(void) {
    struct timespec ts;
    ts.tv_sec = (time_t)ttyclock.option.delay;
    ts.tv_nsec = ttyclock.option.nsdelay;

    if (ttyclock.option.screensaver || ttyclock.option.tty) {
        /* nanosleep restarts after signals are handled by looping
         * on the remainder it reports (which it leaves at zero
         * when the request itself was invalid). */
        struct timespec rem = ts;
        while (nanosleep(&rem, &rem) < 0 && errno == EINTR) {
            if (sigflag) break;
            if (rem.tv_sec == 0 && rem.tv_nsec == 0) break;
        }
        if (ttyclock.option.screensaver) {
            nodelay(stdscr, TRUE);
            int c = getch();
            nodelay(stdscr, FALSE);
            if (c != ERR) pending = c;
            return pending != ERR;
        }
        return 0;
    }

    int fd = input_fd();
    if (fd < 0) fd = STDIN_FILENO;
    long long total_ns = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;
    (void)total_ns;
    /* remaining time accounting, in nanoseconds */
    long long rem_ns;
    if (ts.tv_sec < 0) {
        rem_ns = 1000000000LL; /* invalid requests behave like 1s */
        if (ts.tv_nsec >= 0 && ts.tv_nsec < 1000000000L)
            rem_ns = 1000000000LL;
    } else if (ts.tv_nsec < 0 || ts.tv_nsec >= 1000000000L) {
        rem_ns = 0;
    } else {
        rem_ns = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;
    }

    int ready = 0;
    while (1) {
        struct timespec slice;
        slice.tv_sec = 0;
        slice.tv_nsec = 1000000L;
        /* Poll for at most one millisecond at a time. */
        fd_set rf;
        FD_ZERO(&rf);
        FD_SET(fd, &rf);
        struct timeval tv;
        tv.tv_sec = 0;
        tv.tv_usec = 1000;
        int r = select(fd + 1, &rf, NULL, NULL, &tv);
        if (r > 0 && FD_ISSET(fd, &rf)) { ready = 1; break; }
        if (sigflag) break;
        if (r == 0) {
            rem_ns -= 1000000LL;
            if (rem_ns <= 0) break;
        } else if (errno != EINTR) {
            /* Unusable descriptor: treat as input-ready (a plain
             * nanosleep here would spin roughly the same way). */
            struct timespec rem = ts;
            nanosleep(&rem, &rem);
            ready = 1;
            break;
        }
        /* r<0 EINTR: loop without charging(?) the millisecond */
    }
    return ready;
}

/* Relocate both windows to the stored position after movement. */
static void move_windows(void) {
    int maxy = getmaxy(stdscr);
    int maxx = getmaxx(stdscr);
    int dlen = (int)strlen(ttyclock.datestr);
    if (ttyclock.datewin && !ttyclock.option.hide_date) {
        int so1 = ttyclock.option.center
            ? (ttyclock.date_w > 10 ? ttyclock.date_w + 2 : 12)
            : (ttyclock.w - dlen) / 2 + 1;
        int so2 = ttyclock.w - ttyclock.date_w +
                  ((ttyclock.date_w - dlen) / 2);
        int nx = ttyclock.x + (so1 > so2 ? so2 : so1) - 1;
        int ny = ttyclock.option.center
            ? (maxy - ttyclock.h) / 2 + 6 : ttyclock.y + ttyclock.h - 1;
        if (mvwin(ttyclock.datewin, ny, nx) == OK) {
            ttyclock.date_y = ny;
            ttyclock.date_x = nx;
        }
    }
    (void)maxx;
    mvwin(ttyclock.clockwin, ttyclock.y, ttyclock.x);
}

/* Bounds shared by movement keys and rebound. */
static int xmax_pos(void) { return getmaxx(stdscr) - ttyclock.w; }
static int ymax_pos(void) { return getmaxy(stdscr) - 9; }

void draw_date(void) {
    if (!ttyclock.datewin) return;
    int dlen = (int)strlen(ttyclock.datestr);
    int need = dlen + 2;
    if (need != ttyclock.date_w) {
        layout_dirty = 1;
        return;
    }
    if (ttyclock.option.bold) wattron(ttyclock.datewin, A_BOLD);
    wattron(ttyclock.datewin, COLOR_PAIR(2));
    int centered_content = ttyclock.date_w - 2;
    int off = 1;
    if (ttyclock.option.center)
        off = 1 + (centered_content - dlen) / 2;
    mvwaddstr(ttyclock.datewin, 1, off, ttyclock.datestr);
    wattroff(ttyclock.datewin, COLOR_PAIR(2));
    if (ttyclock.option.bold) wattroff(ttyclock.datewin, A_BOLD);
    wrefresh(ttyclock.datewin);
}

static void draw_all(void) {
    update_time();
    if (ttyclock.option.box) set_box();
    draw_clock();
    draw_date();
}

/* Handle one key.  Returns 0 if the program should exit. */
static int handle_key(int key) {
    if (key == ERR) return 1;

    if (key == KEY_RESIZE) {
        layout_dirty = 1;
        return 1;
    }

    /* Arrow keys behave exactly like the vi movement keys. */
    if (key == KEY_LEFT) key = 'h';
    else if (key == KEY_DOWN) key = 'j';
    else if (key == KEY_UP) key = 'k';
    else if (key == KEY_RIGHT) key = 'l';

    switch (key) {
        case 'q':
        case 'Q':
            return ttyclock.option.dontquit ? 1 : 0;

        case 'h': case 'H':
            if (!ttyclock.option.center && ttyclock.x > 0) {
                ttyclock.x--;
                move_windows();
            }
            break;
        case 'l': case 'L': {
            int xm = xmax_pos();
            if (!ttyclock.option.center && xm >= 0 && ttyclock.x < xm) {
                ttyclock.x++;
                move_windows();
            }
            break;
        }
        case 'k': case 'K':
            if (!ttyclock.option.center && ttyclock.y > 0) {
                ttyclock.y--;
                move_windows();
            }
            break;
        case 'j': case 'J': {
            int ym = ymax_pos();
            if (!ttyclock.option.center && ym >= 0 && ttyclock.y < ym) {
                ttyclock.y++;
                move_windows();
            }
            break;
        }

        case 'c': case 'C':
            ttyclock.option.center = !ttyclock.option.center;
            if (ttyclock.option.center) ttyclock.option.rebound = 0;
            layout_dirty = 1;
            break;

        case 'x': case 'X':
            ttyclock.option.box = !ttyclock.option.box;
            if (!ttyclock.option.box) {
                werase(stdscr);
                wrefresh(stdscr);
                if (ttyclock.clockwin) {
                    werase(ttyclock.clockwin);
                    touchwin(ttyclock.clockwin);
                }
                if (ttyclock.datewin) {
                    werase(ttyclock.datewin);
                    touchwin(ttyclock.datewin);
                }
            }
            break;

        case 'b': case 'B':
            ttyclock.option.bold = !ttyclock.option.bold;
            /* Existing digit cells keep their old attributes in the
             * reference until redrawn; ncurses repaints changed
             * cells on the next refresh the same way here. */
            break;

        case 'r': case 'R':
            ttyclock.option.rebound = !ttyclock.option.rebound;
            break;

        case 's': case 'S':
            ttyclock.option.second = !ttyclock.option.second;
            layout_dirty = 1;
            break;

        case 't': case 'T':
            ttyclock.option.twelve = !ttyclock.option.twelve;
            layout_dirty = 1;
            break;

        case '0': case '1': case '2': case '3':
        case '4': case '5': case '6': case '7':
            if (ttyclock.option.screensaver) {
                /* Inside the screensaver only the colour keys are
                 * acted on.  Queue the colour change so it takes
                 * effect two redraws from now. */
                extern void queue_color(int);
                queue_color(key - '0');
            } else {
                ttyclock.option.color = key - '0';
                init_pair(1, ttyclock.option.color, ttyclock.option.color);
                init_pair(2, ttyclock.option.color, -1);
            }
            break;

        default:
            break;
    }
    return 1;
