static int input_fd(void) {
    /* The stream the clock screen reads keys from.
     * When -T was used, try to recover the descriptor from the tty
     * name; input will be opened once and cached. */
    static int fd = -2;
    if (fd == -2) {
        if (ttyclock.option.tty) {
            FILE *probe = fopen(ttyclock.option.tty, "r+");
            fd = probe ? fileno(probe) : STDIN_FILENO;
            /* Note: this descriptor is NOT used for curses input
             * (the SCREEN has its own); it is only polled to decide
             * when to sleep, and polling it must not consume input. */
        } else {
            fd = STDIN_FILENO;
        }
        /* In -T mode the reference behaviour sleeps with nanosleep
         * and never wakes early on the remote tty either, which the
         * wait routine reproduces without needing this descriptor.
         * Keep it for the local case only. */
        if (ttyclock.option.tty) fd = -1;
    }
    return fd;
