/*
 * Sleep for the configured delay, waking early when a key becomes
 * readable on the local input.  Returns 1 if input is ready.
 *
 * In screensaver mode (and always when showing on a remote tty)
 * the sleep is never shortened: keys are only discovered at the
 * end of the delay.  A zero total delay is still a nanosleep.
 */
static int wait_delay(void) {
    struct timespec ts;
    ts.tv_sec = (time_t)ttyclock.option.delay;
    ts.tv_nsec = ttyclock.option.nsdelay;

    if (ttyclock.option.screensaver || ttyclock.option.tty) {
        /* nanosleep restarts after signals are handled by looping
         * on the remainder it reports (which it leaves at zero
         * when the request itself was invalid). */
        struct timespec rem = ts;
        while (nanosleep(&rem, &rem) < 0 && errno == EINTR) {
            if (sigflag) break;
            if (rem.tv_sec == 0 && rem.tv_nsec == 0) break;
        }
        if (ttyclock.option.screensaver) {
            nodelay(stdscr, TRUE);
            int c = getch();
            nodelay(stdscr, FALSE);
            if (c != ERR) pending = c;
            return pending != ERR;
        }
        return 0;
    }

    int fd = input_fd();
    if (fd < 0) fd = STDIN_FILENO;
    long long total_ns = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;
    (void)total_ns;
    /* remaining time accounting, in nanoseconds */
    long long rem_ns;
    if (ts.tv_sec < 0) {
        rem_ns = 1000000000LL; /* invalid requests behave like 1s */
        if (ts.tv_nsec >= 0 && ts.tv_nsec < 1000000000L)
            rem_ns = 1000000000LL;
    } else if (ts.tv_nsec < 0 || ts.tv_nsec >= 1000000000L) {
        rem_ns = 0;
    } else {
        rem_ns = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;
    }

    int ready = 0;
    while (1) {
        struct timespec slice;
        slice.tv_sec = 0;
        slice.tv_nsec = 1000000L;
        /* Poll for at most one millisecond at a time. */
        fd_set rf;
        FD_ZERO(&rf);
        FD_SET(fd, &rf);
        struct timeval tv;
        tv.tv_sec = 0;
        tv.tv_usec = 1000;
        int r = select(fd + 1, &rf, NULL, NULL, &tv);
        if (r > 0 && FD_ISSET(fd, &rf)) { ready = 1; break; }
        if (sigflag) break;
        if (r == 0) {
            rem_ns -= 1000000LL;
            if (rem_ns <= 0) break;
        } else if (errno != EINTR) {
            /* Unusable descriptor: treat as input-ready (a plain
             * nanosleep here would spin roughly the same way). */
            struct timespec rem = ts;
            nanosleep(&rem, &rem);
            ready = 1;
            break;
        }
        /* r<0 EINTR: loop without charging(?) the millisecond */
    }
    return ready;
}

